export type LibraryItemType = 'folder' | 'document' | 'file';

export interface LibraryItem {
  /** Stable internal UUID generated by Electron Main */
  id: string;
  /** Display name of the item or folder */
  name: string;
  /** Item type discriminator */
  type: LibraryItemType;
  /** Parent folder UUID, or null for root directory */
  parentId: string | null;
  /** Creation timestamp in milliseconds (epoch) */
  createdAt: number;
  /** Last modification timestamp in milliseconds (epoch) */
  updatedAt: number;
  /** Soft-delete state flag for archiving and trash recovery */
  isDeleted: boolean;
  /** Extensible metadata */
  metadata?: {
    size?: number;
    description?: string;
    tags?: string[];
    mimeType?: string;
    [key: string]: unknown;
  };
}

export interface LibraryStoreData {
  schemaVersion: 1;
  items: LibraryItem[];
}

export interface CreateLibraryItemOptions {
  name: string;
  type: LibraryItemType;
  parentId?: string | null;
  metadata?: LibraryItem['metadata'];
}

export interface UpdateLibraryItemOptions {
  name?: string;
  metadata?: LibraryItem['metadata'];
}

export interface MoveLibraryItemOptions {
  newParentId: string | null;
}

export interface ListLibraryItemsFilter {
  parentId?: string | null;
  includeDeleted?: boolean;
}

export interface LibraryBridge {
  list: (filter?: ListLibraryItemsFilter) => Promise<LibraryItem[]>;
  get: (id: string) => Promise<LibraryItem | null>;
  create: (options: CreateLibraryItemOptions) => Promise<LibraryItem>;
  update: (id: string, updates: UpdateLibraryItemOptions) => Promise<LibraryItem>;
  move: (id: string, newParentId: string | null) => Promise<LibraryItem>;
  delete: (id: string) => Promise<boolean>;
}

export interface ILibraryStorageRepository {
  listItems(filter?: ListLibraryItemsFilter): Promise<LibraryItem[]>;
  getItem(id: string): Promise<LibraryItem | null>;
  createItem(options: CreateLibraryItemOptions): Promise<LibraryItem>;
  updateItem(id: string, updates: UpdateLibraryItemOptions): Promise<LibraryItem>;
  moveItem(id: string, newParentId: string | null): Promise<LibraryItem>;
  deleteItem(id: string): Promise<boolean>;
}
